import contextlib
import io
import json
import math

CANDIDATE = 'block-0.txt'
HTML_FILE = 'your_html_file.html'


def normalize(v):
    if v is None:
        return None
    if isinstance(v, float) and math.isnan(v):
        return None
    if isinstance(v, (str, int, float, bool)):
        return v
    return str(v)


def run_case(source, html):
    with open(HTML_FILE, 'w', encoding='utf-8') as f:
        f.write(html)
    ns = {'__name__': '__candidate__'}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        exec(compile(source, CANDIDATE, 'exec'), ns)
    if 'df' not in ns:
        raise RuntimeError('candidate did not define df')
    df = ns['df']
    columns = [str(c) for c in list(df.columns)]
    rows = [[normalize(v) for v in row] for row in df.values.tolist()]
    return {'columns': columns, 'rows': rows}


def main():
    try:
        with open('inputs.json', 'r', encoding='utf-8') as f:
            cases = json.load(f)
        with open(CANDIDATE, 'r', encoding='utf-8') as f:
            source = f.read()
    except Exception as e:
        print(json.dumps({'results': [], 'harness_error': 'setup failed: ' + repr(e)}))
        return
    results = []
    for case in cases:
        cid = case.get('id') if isinstance(case, dict) else None
        try:
            html = case['input']['html']
            actual = run_case(source, html)
            results.append({'id': cid, 'actual': actual})
        except Exception as e:
            results.append({'id': cid, 'error': type(e).__name__ + ': ' + str(e)})
    print(json.dumps({'results': results}, ensure_ascii=False))


if __name__ == '__main__':
    main()

import contextlib
import io
import json
import signal
import sys


class CaseTimeout(Exception):
    pass


def _on_alarm(signum, frame):
    raise CaseTimeout("candidate timed out after 5 seconds")


def emit(obj):
    sys.stdout.write(json.dumps(obj))
    sys.stdout.flush()


def normalize(df):
    columns = [str(c) for c in list(df.columns)]
    rows = [[str(v) for v in row] for row in df.itertuples(index=False, name=None)]
    return {"columns": columns, "rows": rows}


def run_case(case_id, src):
    ns = {"__name__": "__main__"}
    old = signal.signal(signal.SIGALRM, _on_alarm)
    signal.alarm(5)
    try:
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            code = compile(src, "block-0.txt", "exec")
            exec(code, ns)
        if "df" not in ns:
            return {"id": case_id, "error": "candidate did not define df"}
        return {"id": case_id, "actual": normalize(ns["df"])}
    except Exception as e:
        return {"id": case_id, "error": type(e).__name__ + ": " + str(e)}
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, old)


def main():
    try:
        with open("inputs.json", encoding="utf-8") as fh:
            cases = json.load(fh)
        with open("block-0.txt", encoding="utf-8") as fh:
            src = fh.read()
        import pandas  # noqa: F401
    except Exception as e:
        emit({"results": [], "harness_error": "setup failed: " + type(e).__name__ + ": " + str(e)})
        return

    results = []
    for case in cases:
        case_id = case.get("id")
        try:
            html = case["input"]["html"]
            with open("table.html", "w", encoding="utf-8") as fh:
                fh.write(html)
        except Exception as e:
            emit({"results": results, "harness_error": "could not stage input " + str(case_id) + ": " + str(e)})
            return
        results.append(run_case(case_id, src))

    emit({"results": results})


if __name__ == "__main__":
    main()
